//! Handlers of committed events: policies and projections.
//!
//! - [`Policy`] (Event Storming's term; an *automation* in Event
//!   Modeling): event → **commands** to target streams. ONE trait, whether
//!   written by hand or generated by the markup (`#[policy]`), registered
//!   in ONE list ([`Registry::policy`](super::Registry::policy)) and run
//!   in registration order. A command goes through the target's five steps
//!   and may be refused. **A policy's only output is commands**: facts come
//!   from outside the system only, so there is no policy-injected fact.
//!   Propagating one aggregate's changes into another (hatpick's list into
//!   its draw systems) is a policy whose target records the change in its
//!   own events.
//! - [`Projection`]: event → a read model's fold. It produces nothing. Read
//!   models are replayed from the stream on every read.
//!
//! A policy's command is a `CommandBook` the kernel builds: the target's
//! cover, a `Command` page whose payload is the policy's command packed as
//! `Any`, and **no ids and no handling**. The kernel checks it like any
//! book, then identifies it from its trigger: command id
//! [`ids::policy_command_id`](super::ids::policy_command_id)(trigger,
//! [`Policy::NAME`], index), the trigger's correlation, and the trigger as
//! its `causation_id`. Nothing outside the kernel can build one. The
//! command's events name the command as their causation
//! (`EventMeta.causation.command_id`), never the trigger: the trigger edge
//! is the command's, for tracing.
//!
//! A target's cover is the target domain's, in **the source's edition**: a
//! policy never crosses timelines.
//!
//! **Targeting from the event.** [`Policy::on_event`] receives the event
//! with its trigger and correlation, so a policy may forward **only some
//! events**: hatpick's list forwards content changes to its draw systems
//! and keeps its invites to itself. A target is sent commands for the
//! source events it was targeted for, in source order.

use std::sync::Arc;

use angzarr_embedded_diagnostic::Report;
use angzarr_proto::v1::angzarr_dead_letter::Payload as Letter;
use angzarr_proto::v1::{
    command_page, Command, CommandBook, CommandPage, Cover, EventBook, EventPage, EventRef, Uuid,
};
use angzarr_router::policy::PolicyDispatch;
use prost_types::Any;

use super::check::{check_policy_command, Checked, Malformed};
use super::dead_letter::{write_dead_letter, write_policy_failure, DeadLetterLog};
use super::domain::Domain;
use super::handler::{Committed, Handler};
use super::markup::{self, CommandContext, Commands, PolicyContext, TypeName};
use super::payload::{type_name, Payload};
use super::registry::Registry;

// ---------------------------------------------------------------- policies

/// Event → commands: one source domain, one target domain, and the
/// commands each source event is owed, each with the root of the target
/// stream it is for. Stateless: what it owes is a function of the event.
///
/// **Policies should not fail for business reasons**: they react to events
/// the application's own domains created, so an `Err` from
/// [`Policy::on_event`] is a bug. It fails the step as
/// [`StepError::PolicyFailed`](super::StepError::PolicyFailed), a defect,
/// dead-lettered by its code and args, its position moved past the
/// trigger.
/// Each command is decided by its target and may be refused: a policy that
/// answers refusals ([`Policy::ANSWERS_REFUSALS`], every marked-up one)
/// delivers its refusal fact to the source ([`Policy::on_refused`]);
/// another's refused command fails its step
/// ([`Failure::Downstream`](super::Failure::Downstream) with
/// [`StepError::Rejected`](super::StepError::Rejected)), the step
/// dead-lettered and its position moved past it.
pub trait Policy: Send + Sync + 'static {
    /// The policy's name, stable across releases and never empty: the
    /// `component` its commands' ids are derived from, and its position's
    /// handler. Changing it changes every derived command id.
    ///
    /// The ids name nothing else of the policy: not a rules version, not
    /// its code. A re-run over a trigger it already handled (a redelivery,
    /// a resume) re-derives the same ids and deduplicates, even if the
    /// policy now decides differently. Repairs are new commands with new
    /// ids, appended after what the old code wrote; history is never
    /// rewritten (angzarr decision 13.4).
    const NAME: &'static str;
    /// The one domain whose events it handles, and to which it delivers
    /// its refusal facts.
    type Source: Domain;
    /// The one domain it sends commands to.
    type Target: Domain;
    /// The events it handles, in marker order (a marked-up policy's); empty
    /// for a hand-written one, which reads every event of its source.
    const EVENTS: &'static [TypeName] = &[];
    /// The commands whose refusals it translates: those its
    /// `#[on_refused]` callbacks name, in marker order.
    const TRANSLATES: &'static [TypeName] = &[];
    /// Whether a refusal of its command is answered by its refusal fact to
    /// the source ([`Policy::on_refused`]): angzarr's refusal flow, every
    /// marked-up policy's. A policy that does not has its refused command
    /// fail the step.
    const ANSWERS_REFUSALS: bool = false;

    /// The commands this policy sends for `event` (an event of its source,
    /// packed), each with its target stream's root; `None` for an event it
    /// does not handle; or why it cannot answer the event, a bug (an event
    /// that cannot happen, or one of a type it handles that does not
    /// decode): its step fails as
    /// [`StepError::PolicyFailed`](super::StepError::PolicyFailed), is
    /// dead-lettered with the error's code as its reason and its args as
    /// the letter's metadata, and its position moves past the event.
    /// Policies should not fail for business reasons: they react to events
    /// the application's own domains created, so an `Err` is a bug.
    fn on_event(
        &self,
        event: &Any,
        ctx: &PolicyContext,
    ) -> Result<Option<Commands<Self::Target>>, Report>;

    /// angzarr's `PolicyService.OnRefused`: the refusal fact's payload for
    /// the policy's source, packed. Pass-through by default: angzarr's
    /// `CommandRefused { command, refusal, trigger }`, `refusal` the
    /// response's object still packed, `trigger` the triggering event's
    /// `EventRef`. A marked-up policy's `#[on_refused]` callback translates
    /// instead. The chain addresses it to the trigger's stream and stamps
    /// its identity.
    ///
    /// `ctx` is the refused command's context as the kernel delivered it:
    /// its target's cover, its command id and its correlation. An error is a bug, as `on_event`'s is: the step fails as
    /// [`StepError::PolicyFailed`](super::StepError::PolicyFailed), is
    /// dead-lettered by the error's code and args, and the policy's
    /// position moves past the trigger.
    fn on_refused(
        &self,
        refusal: &markup::v1::Refusal,
        ctx: &CommandContext,
    ) -> Result<Any, Report> {
        let _ = ctx;
        Ok(markup::__pass_through(refusal))
    }
}

/// Event → read model. Produces nothing. Read models are replayed from the
/// stream on every read ([`Stream::dispatch`](super::Stream::dispatch) from 0).
pub trait Projection<D: Domain> {
    fn project(&mut self, committed: &Committed<'_, D>);
}

// ---------------------------------------------------------------- dispatch

/// One command a policy owes one target, before the kernel books it.
/// Built only by the kernel, from a committed event.
pub struct Order {
    pub(crate) policy: String,
    pub(crate) cover: Cover,
    pub(crate) command: Any,
    pub(crate) trigger: EventRef,
    pub(crate) index: u32,
    pub(crate) correlation_id: Uuid,
}

impl Order {
    /// The target's stream.
    pub fn cover(&self) -> &Cover {
        &self.cover
    }

    /// The command, packed.
    pub fn command(&self) -> &Any {
        &self.command
    }

    /// The source event: the command's causation (not its events').
    pub fn trigger(&self) -> &EventRef {
        &self.trigger
    }

    /// The command's index among those the trigger set off for this
    /// policy, in order.
    pub fn index(&self) -> u32 {
        self.index
    }

    /// The trigger's correlation, which the command keeps.
    pub fn correlation_id(&self) -> &Uuid {
        &self.correlation_id
    }

    /// The order as a book, checked through the kernel's policy entry:
    /// the target's cover, the command packed as `Any`, no ids, no
    /// handling. Malformed only by a bug (a policy or kernel one).
    pub(crate) fn check(&self, registry: &Registry) -> Result<Checked, Malformed> {
        check_policy_command(
            self.book(),
            registry,
            self.trigger.clone(),
            &self.policy,
            self.index,
            self.correlation_id.clone(),
        )
    }

    /// [`Order::check`], writing a dead letter for a malformed book: only a
    /// bug makes one.
    pub(crate) fn check_logged(
        &self,
        registry: &Registry,
        dead_letters: &dyn DeadLetterLog,
    ) -> Result<Checked, Malformed> {
        self.check(registry).inspect_err(|malformed| {
            write_dead_letter(
                dead_letters,
                self.book(),
                &self.policy,
                &malformed.to_string(),
            )
        })
    }

    /// The order as the kernel books it: the target's cover, the command
    /// packed as `Any`, no ids, no handling.
    pub(crate) fn book(&self) -> CommandBook {
        CommandBook {
            cover: Some(self.cover.clone()),
            page: Some(CommandPage {
                body: Some(command_page::Body::Command(Command {
                    payload: Some(self.command.clone()),
                })),
                ..CommandPage::default()
            }),
            handling: None,
        }
    }
}

/// A policy as a [`Handler`] of its source: each committed event becomes
/// one [`Order`] per command, handed to `sink` in order. An event the policy
/// fails on hands over nothing, and is dead-lettered to `dead_letters` as
/// the kernel dead-letters a policy's failed step: its error's code as the
/// reason, its args as the metadata.
pub fn policy<'p, P: Policy, F: FnMut(Order)>(
    policy: &'p P,
    dead_letters: &'p dyn DeadLetterLog,
    sink: F,
) -> PolicyHandler<'p, P, F> {
    PolicyHandler {
        policy,
        dead_letters,
        sink,
    }
}

/// A projection as a [`Handler`].
pub fn projection<P>(projection: &mut P) -> Projector<'_, P> {
    Projector(projection)
}

/// See [`policy`].
pub struct PolicyHandler<'p, P, F> {
    policy: &'p P,
    dead_letters: &'p dyn DeadLetterLog,
    sink: F,
}

/// See [`projection`].
pub struct Projector<'p, P>(&'p mut P);

impl<P: Policy, F: FnMut(Order)> Handler<P::Source> for PolicyHandler<'_, P, F> {
    fn handle(&mut self, committed: &Committed<'_, P::Source>) {
        let ctx = PolicyContext::new(
            committed.event_ref(),
            committed.envelope.correlation_id().clone(),
            committed.envelope.recorded_at(),
        );
        let event = committed.event().to_any();
        let commands = match self.policy.on_event(&event, &ctx) {
            Ok(Some(commands)) => commands,
            Ok(None) => return,
            Err(failure) => {
                let trigger = EventBook {
                    cover: Some(committed.cover.clone()),
                    pages: vec![EventPage {
                        sequence: committed.sequence(),
                        payload: Some(event),
                        ..EventPage::default()
                    }],
                    ..EventBook::default()
                };
                write_policy_failure(
                    self.dead_letters,
                    Letter::RejectedEvents(trigger),
                    P::NAME,
                    &failure,
                );
                return;
            }
        };
        let target = <P::Target as Domain>::NAME;
        for order in orders(
            P::NAME,
            target,
            committed.cover,
            &ctx,
            commands.into_orders(),
        ) {
            (self.sink)(order);
        }
    }
}

impl<D: Domain, P: Projection<D>> Handler<D> for Projector<'_, P> {
    fn handle(&mut self, committed: &Committed<'_, D>) {
        self.0.project(committed)
    }
}

/// The stream a policy's command for `root` goes to, for a source event in
/// `source`: the target domain's, in the source's edition.
pub fn target_cover<P: Policy>(source: &Cover, root: &Uuid) -> Cover {
    cover_in(<P::Target as Domain>::NAME, source, root)
}

/// `domain`'s stream at `root`, in `source`'s edition.
pub(crate) fn cover_in(domain: &str, source: &Cover, root: &Uuid) -> Cover {
    Cover {
        domain: domain.to_string(),
        root: Some(root.clone()),
        edition: source.edition.clone(),
    }
}

/// The orders a policy named `policy` owes for the event `ctx` names in
/// `source`, its `commands` to `target`'s streams in order, the `index`th
/// command's index `index`.
pub(crate) fn orders(
    policy: &str,
    target: &str,
    source: &Cover,
    ctx: &PolicyContext,
    commands: Vec<(Uuid, Any)>,
) -> Vec<Order> {
    (0..)
        .zip(commands)
        .map(|(index, (root, command))| Order {
            policy: policy.to_string(),
            cover: cover_in(target, source, &root),
            command,
            trigger: ctx.trigger().clone(),
            index,
            correlation_id: ctx.correlation_id().clone(),
        })
        .collect()
}

/// The orders policy `policy` owes for `trigger` (in `correlation_id`):
/// the router's answer, `books`, each the target's stream (the router held
/// it to the trigger's edition, a named root and the trigger's
/// correlation) and its command, in order.
pub(crate) fn answered(
    policy: &str,
    trigger: &EventRef,
    correlation_id: &Uuid,
    books: Vec<CommandBook>,
) -> Vec<Order> {
    (0..)
        .zip(books)
        .map(|(index, book)| Order {
            policy: policy.to_string(),
            cover: book.cover.unwrap_or_default(),
            command: match book.page.and_then(|p| p.body) {
                Some(command_page::Body::Command(command)) => command.payload.unwrap_or_default(),
                Some(command_page::Body::Fact(fact)) => fact.payload.unwrap_or_default(),
                None => Any::default(),
            },
            trigger: trigger.clone(),
            index,
            correlation_id: correlation_id.clone(),
        })
        .collect()
}

/// The refused command's context, from the command `refusal` carries as
/// the kernel delivered it: its target's cover and its identity (its
/// derived command id and the trigger's correlation). A policy's command
/// carries no handling and is never a fact, and what only the target's
/// dispatch knew (its next sequence, whether it had history, a conflict) is
/// not carried: those stay default.
fn refused_context(refusal: &markup::v1::Refusal) -> CommandContext {
    let book = refusal.command.clone().unwrap_or_default();
    let page = book.page.unwrap_or_default();
    CommandContext {
        cover: book.cover,
        command_id: page.command_id,
        correlation_id: page.correlation_id,
        ..CommandContext::default()
    }
}

/// `policy` as angzarr-router's table: each event type it handles (its
/// `EVENTS`, or every event of its source for a hand-written one) runs
/// [`Policy::on_event`] with the trigger's place and metadata, each command
/// for the target's stream at the root it names; and, for a policy that
/// answers refusals, each command type it translates (its `TRANSLATES`, or
/// every command of its target for a hand-written one) is answered by
/// [`Policy::on_refused`], with the refused command's context; either's
/// error is carried as the policy's failure. The router holds the answer to the policy's one
/// destination, the trigger's edition, a named root and the trigger's
/// correlation.
pub(crate) fn dispatch<P: Policy>(policy: P) -> PolicyDispatch {
    let policy = Arc::new(policy);
    let target = <P::Target as Domain>::NAME;
    let mut table = PolicyDispatch::new(P::NAME, <P::Source as Domain>::NAME, target);
    let events: Vec<String> = match P::EVENTS.is_empty() {
        true => <<P::Source as Domain>::Event as Payload>::type_urls()
            .iter()
            .map(|url| type_name(url).to_string())
            .collect(),
        false => P::EVENTS.iter().map(TypeName::full_name).collect(),
    };
    for event_type in events {
        let policy = Arc::clone(&policy);
        table = table.on_event_with_context(&event_type, move |event, page| {
            let meta = page.meta.cloned().unwrap_or_default();
            let ctx = PolicyContext::new(
                EventRef {
                    stream: page.cover.cloned(),
                    sequence: page.sequence,
                },
                meta.correlation_id.unwrap_or_default(),
                meta.recorded_at.unwrap_or_default(),
            );
            let commands = policy
                .on_event(event, &ctx)
                .map_err(|failure| super::route::policy_failed(&failure))?
                .map_or_else(Vec::new, Commands::into_orders);
            Ok(commands
                .into_iter()
                .map(|(root, command)| CommandBook {
                    cover: Some(Cover {
                        domain: target.to_string(),
                        root: Some(root),
                        edition: None,
                    }),
                    page: Some(CommandPage {
                        body: Some(command_page::Body::Command(Command {
                            payload: Some(command),
                        })),
                        ..CommandPage::default()
                    }),
                    handling: None,
                })
                .collect())
        });
    }
    if P::ANSWERS_REFUSALS {
        let translated: Vec<String> = match P::TRANSLATES.is_empty() {
            true => <<P::Target as Domain>::Command as Payload>::type_urls()
                .iter()
                .map(|url| type_name(url).to_string())
                .collect(),
            false => P::TRANSLATES.iter().map(TypeName::full_name).collect(),
        };
        for command_type in translated {
            let policy = Arc::clone(&policy);
            table = table.on_refused(&command_type, move |refusal| {
                policy
                    .on_refused(refusal, &refused_context(refusal))
                    .map_err(|failure| super::route::policy_failed(&failure))
            });
        }
    }
    table
}
